export const CHIP_QUERIES = ["wireless earbuds", "air fryer", "running shoes", "smartwatch", "mixer grinder", "5G phone"];

export const fmt = (s, v = {}) => String(s ?? "").replace(/\{(\w+)\}/g, (_, k) => (v[k] ?? ""));

export function t(lang, key) {
  const pack = STR[lang] || STR.en;
  return pack[key] !== undefined ? pack[key] : STR.en[key];
}

export const isLang = (code) => LANGS.some((l) => l.code === code);

