    fac: { fastDelivery: "தகுதியான பொருட்களுக்கு வேகமான டெலிவரி", easyReturns: "பெரும்பாலான பொருட்களுக்கு எளிய ரிட்டர்ன்", cod: "தகுதியான ஆர்டர்களுக்கு கேஷ் ஆன் டெலிவரி", bankEmi: "வங்கி சலுகைகள் & EMI", wideDelivery: "பெரும்பாலான பின் கோடுகளுக்கு டெலிவரி", tataStore: "டாடா குழும கடை", storePickup: "அருகிலுள்ள கடையில் பெறலாம்", extWarranty: "கூடுதல் வாரண்டி திட்டங்கள்", storeNetwork: "சேவைக்கு இந்தியா முழுவதும் கடைகள்", installation: "பெரிய சாதனங்களுக்கு நிறுவல்", authBrand: "அங்கீகரிக்கப்பட்ட பிராண்ட் விற்பனையாளர்கள்", fashion: "ஃபேஷன் நிபுணர்", sizeExchange: "தகுதியான பொருட்களுக்கு அளவு மாற்றம்", relFashion: "ரிலையன்ஸ் ஃபேஷன் தளம்", beauty: "அழகு சாதன நிபுணர்", authentic: "பிராண்டுகளின் உண்மையான பொருட்கள்" }
